[Form]
public class NDXItemScopeHistory extends FormRun
{
    FormListControl _list, _listYear;
    ItemId          itemId;
    ReqTrans        callerReqTrans;
    InventTransferLine  callerInventTransferLine;                              
    yr              curYear;

    [FormObservable]
    QtyAverage      ConsumpCurMonth, ConsumpMedian;

    [FormObservable]
    Qty             PhysOnHand, PhysScope, AvailOnHand, AvailScope;

    [FormObservable]
    QtyAverage      ConsumpCurMonthInventSite;

    [FormObservable]
    Qty             PhysScopeInventSite, AvailScopeInventSite;

    [FormObservable]
    InventUnitId    unitId;
    [FormObservable]
    InventSiteId    inventSiteId;

}

void setListViewMonthlyValues()
{
    KCS_ItemScopeHistory    curScopeHistory, prevScopeHistory;
    int                     monthCounter;
    yr                      prevYear;
    FormListItem            fli;
    int                     idx;
    ;

    ListViewMonthlyValues.deleteAll();

    prevYear    = curYear - 1;

    for(monthCounter = 1; monthCounter <= 12; monthCounter++)
    {
        curScopeHistory     = KCS_ItemScopeHistory::find(ItemId, curYear, monthCounter);
        prevScopeHistory    = KCS_ItemScopeHistory::find(ItemId, prevYear, monthCounter);

        fli = new FormListItem(mthname(monthCounter),1);
        fli.idx(monthCounter);
        idx = ListViewMonthlyValues.addItem(fli);
        ListViewMonthlyValues.setText(idx, num2str(abs(prevScopeHistory.ConsumpSum),0,2,2,1), 1);
        ListViewMonthlyValues.setText(idx, num2str(abs(curScopeHistory.ConsumpSum),0,2,2,1), 2);
    }

}

void setListViewYearlyValues()
{
    KCS_ItemScopeHistory    curScopeHistory;
    yr                      minYear;
    FormListItem            fli;
    int                     idx;
    ;

    ListViewYearlyValues.deleteAll();

    select firstOnly curScopeHistory order by HistoryDate                                  
                                where curScopeHistory.ItemId == ItemId;

    minYear = year(curScopeHistory.HistoryDate);
    if (!curScopeHistory.RecId)
    {
        minYear = curYear;
    }

    if ((curYear - 6) > minYear)
    {
        minYear = curYear - 6;
    }

    while (minYear <= curYear)
    {
        select sum(ConsumpSum) from curScopeHistory where curScopeHistory.ItemId == ItemId
                                                   && curScopeHistory.Year   == minYear;

        fli = new FormListItem(int2str(minYear),1);
        fli.idx(minYear);
        idx = ListViewYearlyValues.addItem(fli);
        ListViewYearlyValues.setText(idx, num2str(abs(curScopeHistory.ConsumpSum),0,2,2,1), 1);
        minYear++;
    }
}

void setCurrentValues()
{
    NDXItemScopeHistory        itemScopeHistory = NDXItemScopeHistory::construct();
    ;

    if (callerReqTrans)
    {
        itemScopeHistory.initFromReqTrans(callerReqTrans);
    }
    else if (callerInventTransferLine)
    {            
        itemScopeHistory.initFromInventTransferLine(callerInventTransferLine);
    }
    itemScopeHistory.parmCurYear(curYear);

    [ConsumpCurMonth,
     ConsumpMedian,
     PhysOnHand,
     AvailOnHand,
     PhysScope,
     AvailScope,
     ConsumpCurMonthInventSite,
     PhysScopeInventSite,
     AvailScopeInventSite] = itemScopeHistory.setCurrentValues();
}

display itemId itemId()
{
    return  callerReqTrans ? callerReqTrans.ItemId : callerInventTransferLine.ItemId;
}

public void init()
{

    KCS_ItemScopeHistory    itemScopeHistory;                                
    ;

    super(); 

    curYear     = year(DateTimeUtil::date(DateTimeUtil::getSystemDateTime()));

    if (!element.args()             ||
    !element.args().record()    ||
     (element.args().record().TableId != tablenum(ReqTrans)
     && element.args().record().TableId != tablenum(InventTransferLine)))    
    {
        throw Error("@NDX:NDXIncorrectFormCall");
    }
    else
    {
        if (element.args().record().TableId == tablenum(ReqTrans))
        {
            callerReqTrans  = element.args().record();
            itemId = callerReqTrans.ItemId;
        }
        else if (element.args().record().TableId == tablenum(InventTransferLine))
        {
            callerInventTransferLine = element.args().record();
            itemId = callerInventTransferLine.ItemId;
        }
        inventSiteId = callerReqTrans ? callerReqTrans.inventDim().inventSiteId : InventLocation::find(callerInventTransferLine.inventTransferTable().InventLocationIdTo).InventSiteId;
    }

    unitId = callerReqTrans ? callerReqTrans.inventUnitId() : callerInventTransferLine.UnitId;

    _list = ListViewMonthlyValues;

    _list.addColumn(1,new FormListColumn("@NDX:NDXConsump",1, 100));
    _list.addColumn(2,new FormListColumn("@NDX:NDXLastYear",2, 100));
    _list.addColumn(3,new FormListColumn("@NDX:NDXCurrent",3, 100));

    _listYear   = ListViewYearlyValues;

    _listYear.addColumn(1, new FormListColumn("@NDX:NDXYear",1));
    _listYear.addColumn(2, new FormListColumn("@NDX:NDXConsump",2, 100));

    select firstOnly itemScopeHistory order by itemScopeHistory.modifiedDateTime desc;

    if(DateTimeUtil::year(itemScopeHistory.modifiedDateTime) != year(DateTimeUtil::getToday(DateTimeUtil::getUserPreferredTimeZone())) || DateTimeUtil::month(itemScopeHistory.modifiedDateTime) != mthofyr(DateTimeUtil::getToday(DateTimeUtil::getUserPreferredTimeZone())))
    {
        Warning("@NDX:NDXItemScopeNotUpToDate");
    }        
}

/// <summary>
/// DebuC 27.03.24
/// </summary>
public void linkActive()
{
    super();

    if (element.args().record().TableId == tablenum(ReqTrans))
    {
        callerReqTrans  = element.args().record();
        itemId = callerReqTrans.ItemId;
    }            
    else if (element.args().record().TableId == tablenum(InventTransferLine))
    {
        callerInventTransferLine = element.args().record();
        itemId = callerInventTransferLine.ItemId;
    }  
    inventSiteId = callerReqTrans ? callerReqTrans.inventDim().inventSiteId : InventLocation::find(callerInventTransferLine.inventTransferTable().InventLocationIdTo).InventSiteId;
    element.setDesign();
}

/// <summary>
/// DebuC 16.04.24
/// </summary>
public void initPartForm()
{            
    super();

    this.createFieldValueLink(int2Str(classNum(NDXFillItemScopeHistory)),
                                formDataSourceStr(NDXBatchJobFormPart,BatchExists),
                                fieldId2Name(tableNum(Batch),fieldNum(Batch, ClassNumber)));
}
